{"files":[{"content":"#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

static const long long MOD = 1000000007LL;

struct Point {
    int row;
    int col;
    long long ways;
};

static long long mod_pow(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1LL) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1LL;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<Point> blocked;
    blocked.reserve(static_cast<size_t>(m));
    for (int i = 0; i < m; ++i) {
        int row, col;
        cin >> row >> col;
        blocked.push_back({row, col, 0});
    }

    sort(blocked.begin(), blocked.end(), [](const Point& a, const Point& b) {
        if (a.row != b.row) return a.row < b.row;
        return a.col < b.col;
    });
    blocked.erase(unique(blocked.begin(), blocked.end(), [](const Point& a, const Point& b) {
        return a.row == b.row && a.col == b.col;
    }), blocked.end());

    for (const Point& point : blocked) {
        if ((point.row == 0 && point.col == 0) ||
            (point.row == n - 1 && point.col == n - 1)) {
            cout << 0 << '\n';
            return 0;
        }
    }

    const long long blocker_count = static_cast<long long>(blocked.size());
    const long long sparse_pairs = blocker_count * (blocker_count - 1) / 2;
    const long long dense_cells = static_cast<long long>(n) * n;

    // Use the obstacle recurrence when its pair scan is estimated cheaper;
    // otherwise retain a contiguous, one-row dynamic-programming fallback.
    if (sparse_pairs <= dense_cells / 4) {
        const int limit = 2 * n - 2;
        vector<long long> factorial(static_cast<size_t>(limit) + 1, 1);
        vector<long long> inverse_factorial(static_cast<size_t>(limit) + 1, 1);
        for (int i = 1; i <= limit; ++i) {
            factorial[i] = factorial[i - 1] * i % MOD;
        }
        if (limit >= 0) {
            inverse_factorial[limit] = mod_pow(factorial[limit], MOD - 2);
            for (int i = limit; i > 0; --i) {
                inverse_factorial[i - 1] = inverse_factorial[i] * i % MOD;
            }
        }

        const auto choose = [&](int total, int selected) -> long long {
            if (selected < 0 || selected > total) return 0;
            return factorial[total] * inverse_factorial[selected] % MOD *
                   inverse_factorial[total - selected] % MOD;
        };

        for (size_t i = 0; i < blocked.size(); ++i) {
            Point& current = blocked[i];
            long long ways = choose(current.row + current.col, current.row);

            for (size_t j = 0; j < i; ++j) {
                const Point& previous = blocked[j];
                if (previous.row <= current.row && previous.col <= current.col) {
                    const int row_delta = current.row - previous.row;
                    const int col_delta = current.col - previous.col;
                    const long long paths = choose(row_delta + col_delta, row_delta);
                    ways -= previous.ways * paths % MOD;
                    if (ways < 0) ways += MOD;
                }
            }
            current.ways = ways;
        }

        long long answer = choose(2 * n - 2, n - 1);
        for (const Point& point : blocked) {
            const int row_delta = n - 1 - point.row;
            const int col_delta = n - 1 - point.col;
            const long long paths = choose(row_delta + col_delta, row_delta);
            answer -= point.ways * paths % MOD;
            if (answer < 0) answer += MOD;
        }
        cout << answer << '\n';
        return 0;
    }

    vector<int> dp(static_cast<size_t>(n), 0);
    size_t obstacle_index = 0;
    for (int row = 0; row < n; ++row) {
        size_t row_end = obstacle_index;
        while (row_end < blocked.size() && blocked[row_end].row == row) ++row_end;

        size_t row_obstacle = obstacle_index;
        for (int col = 0; col < n; ++col) {
            if (row_obstacle < row_end && blocked[row_obstacle].col == col) {
                dp[col] = 0;
                ++row_obstacle;
            } else {
                long long ways = dp[col];
                if (col > 0) ways += dp[col - 1];
                if (ways >= MOD) ways -= MOD;
                dp[col] = static_cast<int>(ways);
            }
        }
        obstacle_index = row_end;
    }

    cout << dp[n - 1] << '\n';
    return 0;
}
